package service;

import domain.RefundLine;
import domain.RunResult;
import infra.PgsimClient;
import infra.RefundFileWriter;
import store.RefundRepository;

import java.nio.file.Path;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Nightly refund run: every pending refund line goes to the PG in batches of
 * at most maxLines. Batch id = run id + chunk number; the PG settles and is
 * reconciled per batch id.
 */
public class RefundBatchJob {
    private final RefundRepository refunds;
    private final PgsimClient pg;
    private final String mid;
    private final String prefix;
    private final int maxLines;
    private final Path workDir;

    public RefundBatchJob(RefundRepository refunds, PgsimClient pg, String mid, String prefix, int maxLines,
                          Path workDir) {
        this.refunds = refunds;
        this.pg = pg;
        this.mid = mid;
        this.prefix = prefix;
        this.maxLines = maxLines;
        this.workDir = workDir;
    }

    public RunResult run(LocalDate day) {
        String runId = String.format("%s%s-%02d", prefix, day.format(DateTimeFormatter.BASIC_ISO_DATE),
                refunds.nextRunSeq());
        List<RefundLine> pending = new ArrayList<>();
        for (RefundLine l : uniquePending()) {
            // 결제일 당일분은 이번 회차에서 빼고 다음 날 회차로 (CS-4471)
            // TODO: 이거 아직 필요한가? pgsim 4.x 올린 뒤로는 당일 건도 status·txn 다 정상으로 나옴
            if (l.paidOn() != null && !l.paidOn().isBefore(day)) continue;
            pending.add(l);
        }
        List<String> batchIds = new ArrayList<>();
        int completed = 0;
        for (int start = 0, chunk = 1; start < pending.size(); start += maxLines, chunk++) {
            List<RefundLine> part = pending.subList(start, Math.min(pending.size(), start + maxLines));
            String batchId = runId + "-" + chunk;
            Path file = RefundFileWriter.write(workDir, batchId, part);
            int accepted = pg.refund(mid, batchId, file);
            if (accepted != part.size()) {
                throw new IllegalStateException("PG accepted " + accepted + " of " + part.size() + " in " + batchId);
            }
            for (RefundLine l : part) l.submitted(batchId);
            batchIds.add(batchId);
            completed += RefundResultMatcher.apply(part, pg.status(batchId));
        }
        int awaiting = (int) pending.stream().filter(l -> l.status() == RefundLine.Status.SUBMITTED).count();
        return new RunResult(runId, List.copyOf(batchIds), pending.size(), completed, awaiting);
    }

    /** A line queued twice by a CS double-click must be refunded once. */
    private List<RefundLine> uniquePending() {
        Map<String, RefundLine> byKey = new LinkedHashMap<>();
        for (RefundLine l : refunds.pending()) {
            byKey.putIfAbsent(l.orderNo() + "#" + l.lineNo(), l);
        }
        return new ArrayList<>(byKey.values());
    }
}
package service;

import domain.Order;
import domain.OrderLine;
import domain.RefundLine;
import store.OrderRepository;
import store.RefundRepository;

import java.time.LocalDate;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** CS side: accepts a (partial) refund request. Money moves in the nightly refund run. */
public class RefundService {
    private final OrderRepository orders;
    private final RefundRepository refunds;

    public RefundService(OrderRepository orders, RefundRepository refunds) {
        this.orders = orders;
        this.refunds = refunds;
    }

    public String request(String orderNo, List<Integer> lineNos, LocalDate day) {
        Order order = orders.find(orderNo).orElseThrow(() -> new IllegalArgumentException("no order " + orderNo));
        if (lineNos.isEmpty()) throw new IllegalArgumentException("no lines to refund");
        Set<Integer> wanted = new LinkedHashSet<>(lineNos);
        if (wanted.size() != lineNos.size()) throw new IllegalArgumentException("line listed twice");
        Set<Integer> taken = new LinkedHashSet<>();
        for (RefundLine r : refunds.byOrder(orderNo)) taken.add(r.lineNo());
        for (int n : wanted) {
            order.line(n);
            if (taken.contains(n)) throw new IllegalStateException("line " + n + " of " + orderNo + " already refunded");
        }
        String id = refunds.nextRequestId();
        for (int n : wanted) {
            OrderLine line = order.line(n);
            refunds.add(new RefundLine(id, orderNo, n, order.tid(), line.paid(), day, order.paidOn()));
        }
        return id;
    }
}
package domain;

import java.time.LocalDate;

/** Refund of one order line. Mutable status, owned by the refund repository. */
public final class RefundLine {
    public enum Status {
        /** accepted by CS, waiting for the nightly refund run */
        REQUESTED,
        /** sent to the PG in a refund batch, no PG refund number yet */
        SUBMITTED,
        /** PG refund number received */
        DONE
    }

    private final String requestId;
    private final String orderNo;
    private final int lineNo;
    private final String tid;
    private final long amount;
    private final LocalDate requestedOn;
    private final LocalDate paidOn;
    private Status status = Status.REQUESTED;
    private String batchId;
    private String refundNo;

    public RefundLine(String requestId, String orderNo, int lineNo, String tid, long amount, LocalDate requestedOn) {
        this(requestId, orderNo, lineNo, tid, amount, requestedOn, null);
    }

    /** @param paidOn KST date the original payment was made (null if unknown) */
    public RefundLine(String requestId, String orderNo, int lineNo, String tid, long amount, LocalDate requestedOn,
                      LocalDate paidOn) {
        this.requestId = requestId;
        this.orderNo = orderNo;
        this.lineNo = lineNo;
        this.tid = tid;
        this.amount = amount;
        this.requestedOn = requestedOn;
        this.paidOn = paidOn;
    }

    public String requestId() { return requestId; }
    public String orderNo() { return orderNo; }
    public int lineNo() { return lineNo; }
    public String tid() { return tid; }
    public long amount() { return amount; }
    public LocalDate requestedOn() { return requestedOn; }
    public LocalDate paidOn() { return paidOn; }
    public Status status() { return status; }
    public String batchId() { return batchId; }
    public String refundNo() { return refundNo; }

    public void submitted(String batchId) {
        this.status = Status.SUBMITTED;
        this.batchId = batchId;
    }

    public void done(String refundNo) {
        this.status = Status.DONE;
        this.refundNo = refundNo;
    }

    @Override
    public String toString() {
        return requestId + "/" + orderNo + "#" + lineNo + " " + amount + " " + status;
    }
}
package store;

import domain.RefundLine;

import java.util.ArrayList;
import java.util.List;

public class RefundRepository {
    private final List<RefundLine> lines = new ArrayList<>();
    private int requestSeq;
    private int runSeq;

    public synchronized String nextRequestId() {
        return String.format("RQ%05d", ++requestSeq);
    }

    public synchronized int nextRunSeq() {
        return ++runSeq;
    }

    public synchronized void add(RefundLine line) {
        lines.add(line);
    }

    public synchronized List<RefundLine> pending() {
        return lines.stream().filter(l -> l.status() == RefundLine.Status.REQUESTED).toList();
    }

    public synchronized List<RefundLine> byOrder(String orderNo) {
        return lines.stream().filter(l -> l.orderNo().equals(orderNo)).toList();
    }

    public synchronized List<RefundLine> all() {
        return new ArrayList<>(lines);
    }
}
package service;

import domain.RefundLine;
import infra.PgsimClient.RefundRow;
import infra.RefundFileWriter;

import java.util.ArrayList;
import java.util.List;

/** Attaches PG refund numbers from a batch status to the lines we sent in that batch. */
public final class RefundResultMatcher {
    private RefundResultMatcher() {}

    /** Returns how many lines got a refund number. Each PG row is used at most once. */
    public static int apply(List<RefundLine> sent, List<RefundRow> rows) {
        List<RefundRow> free = new ArrayList<>(rows);
        int matched = 0;
        for (RefundLine line : sent) {
            String ref = RefundFileWriter.merchantRef(line);
            for (int i = 0; i < free.size(); i++) {
                RefundRow row = free.get(i);
                if (row.tid().equals(line.tid()) && row.amount() == line.amount() && row.aux().equals(ref)) {
                    line.done(row.refundNo());
                    free.remove(i);
                    matched++;
                    break;
                }
            }
        }
        return matched;
    }
}
package domain;

import java.util.List;

public record RunResult(String runId, List<String> batchIds, int submitted, int completed, int awaiting) {}
package domain;

import java.time.LocalDate;
import java.util.List;

public record Order(String orderNo, String customerId, String tid, List<OrderLine> lines, long coupon,
                    LocalDate paidOn) {
    public long paidTotal() {
        return lines.stream().mapToLong(OrderLine::paid).sum();
    }

    public OrderLine line(int lineNo) {
        return lines.stream().filter(l -> l.lineNo() == lineNo).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("no line " + lineNo + " in " + orderNo));
    }
}
import api.RefundDeskApi;
import domain.CustomerStatement;
import domain.Order;
import domain.RunResult;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** CS console "즉시 환불": returned items go to the PG right away, other requests wait for the nightly run. */
public class RefundNowE2ETest {
    private static final LocalDate ORDER_DAY = LocalDate.of(2026, 10, 7);
    private static final LocalDate DAY = LocalDate.of(2026, 10, 8);

    public static void main(String[] args) throws Exception {
        TestSupport t = new TestSupport("refund-now");
        RefundDeskApi api = new RefundDeskApi(TestSupport.sandbox());

        Order chargers = api.placeOrder("C-2051", List.of("SKU-PB10", "SKU-PB10", "SKU-CB1M"), 0, ORDER_DAY);
        Order caseOrder = api.placeOrder("C-3310", List.of("SKU-AD20", "SKU-CASE"), 0, ORDER_DAY);
        Order films = api.placeOrder("C-1188", List.of("SKU-FILM", "SKU-FILM", "SKU-STND"), 1000, ORDER_DAY);

        api.requestRefund(caseOrder.orderNo(), List.of(2), DAY);
        String id = api.refundNow(chargers.orderNo(), List.of(1, 2), DAY);

        t.test("refundNow returns a request id", () -> TestSupport.check(id != null && id.startsWith("RQ"), "id " + id));

        t.test("returned power banks are refunded by the PG right away", () -> {
            CustomerStatement s = api.statement(chargers.orderNo());
            TestSupport.eq(31_800L, s.refunded(), "refunded by the PG");
            TestSupport.eq(6_900L, s.balance(), "balance");
            Set<String> nos = new HashSet<>();
            for (CustomerStatement.Line l : s.lines()) {
                if (l.lineNo() == 3) {
                    TestSupport.eq("구매", l.state(), "cable kept");
                    continue;
                }
                TestSupport.eq("환불 완료", l.state(), "line " + l.lineNo());
                TestSupport.check(l.refundNo() != null && nos.add(l.refundNo()), "refund number " + l.refundNo());
            }
        });

        t.test("an ordinary request still waits for the nightly run", () -> {
            CustomerStatement s = api.statement(caseOrder.orderNo());
            TestSupport.eq(0L, s.refunded(), "not refunded yet");
            TestSupport.eq("환불 접수", s.lines().get(1).state(), "state");
        });

        t.test("coupon order: the line's paid amount is refunded at once", () -> {
            api.refundNow(films.orderNo(), List.of(1), DAY);
            TestSupport.eq(7_615L, api.statement(films.orderNo()).refunded(), "refunded");
        });

        t.test("an item cannot be refunded twice", () -> {
            try {
                api.refundNow(chargers.orderNo(), List.of(1), DAY);
                throw new AssertionError("second refund of the same item was accepted");
            } catch (IllegalStateException expected) {
                // ok
            }
        });

        t.test("the nightly run sends only what is left", () -> {
            RunResult run = api.runRefunds(DAY);
            TestSupport.eq(1, run.submitted(), "submitted");
            TestSupport.eq(9_900L, api.statement(caseOrder.orderNo()).refunded(), "C-3310 refunded");
            TestSupport.eq(31_800L, api.statement(chargers.orderNo()).refunded(), "C-2051 unchanged");
            TestSupport.eq(List.of(), api.awaitingPg().stream().map(Object::toString).toList(), "awaiting");
        });

        t.finish();
    }
}

